package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"time"
)

type ChatCompletionRequest struct {
	Model    string                   `json:"model"`
	Messages []map[string]string      `json:"messages"`
	Stream   bool                     `json:"stream"`
}

type ChatCompletionChunk struct {
	Choices []struct {
		Delta struct {
			Content string `json:"content"`
		} `json:"delta"`
	} `json:"choices"`
	Usage struct {
		PromptTokens     int `json:"prompt_tokens"`
		CompletionTokens int `json:"completion_tokens"`
		TotalTokens      int `json:"total_tokens"`
	} `json:"usage"`
	Created int `json:"created"`
}

func main() {
	if len(os.Args) > 1 && os.Args[1] == "--help" {
		fmt.Println("Usage: llama-speed [prompt]")
		fmt.Println("Default prompt: 'Hello, write a short story.'")
		os.Exit(0)
	}

	prompt := "Hello, write a short story."
	if len(os.Args) > 1 {
		prompt = os.Args[1]
	}

	url := "http://localhost:8081/v1/chat/completions"

	reqBody := ChatCompletionRequest{
		Model: "test",
		Messages: []map[string]string{
			{"role": "user", "content": prompt},
		},
		Stream: true,
	}

	jsonData, err := json.Marshal(reqBody)
	if err != nil {
		fmt.Fprintf(os.Stderr, "JSON marshal error: %v\n", err)
		os.Exit(1)
	}

	startTime := time.Now()
	firstTokenTime := time.Time{}
	tokensReceived := 0

	req, err := http.NewRequest("POST", url, bytes.NewBuffer(jsonData))
	if err != nil {
		fmt.Fprintf(os.Stderr, "Request error: %v\n", err)
		os.Exit(1)
	}
	req.Header.Set("Content-Type", "application/json")

	client := &http.Client{Timeout: 120 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		fmt.Fprintf(os.Stderr, "HTTP error: %v\n", err)
		os.Exit(1)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(resp.Body)
		fmt.Fprintf(os.Stderr, "HTTP %d: %s\n", resp.StatusCode, string(body))
		os.Exit(1)
	}

	reader := io.Reader(resp.Body)
	buf := make([]byte, 1024)
	lineBuf := ""

	for {
		n, err := reader.Read(buf)
		if n > 0 {
			lineBuf += string(buf[:n])

			for {
				lineEnd := 0
				for i := 0; i < len(lineBuf); i++ {
					if lineBuf[i] == '\n' {
						lineEnd = i
						break
					}
				}
				if lineEnd == 0 && len(lineBuf) > 0 && lineBuf[len(lineBuf)-1] != '\n' {
					break
				}

				line := lineBuf[:lineEnd]
				lineBuf = lineBuf[lineEnd+1:]

				if len(line) == 0 {
					continue
				}

				if line[0] != '{' {
					continue
				}

				line = line[0 : len(line)-1]

				var chunk ChatCompletionChunk
				if err := json.Unmarshal([]byte(line), &chunk); err != nil {
					continue
				}

				if len(chunk.Choices) > 0 && chunk.Choices[0].Delta.Content != "" {
					if firstTokenTime.IsZero() {
						firstTokenTime = time.Now()
					}
					tokensReceived++
				}
			}
		}
		if err != nil {
			break
		}
	}

	totalTime := time.Since(startTime)

	if !firstTokenTime.IsZero() && tokensReceived > 0 {
		generationTime := firstTokenTime.Sub(startTime)
		tokensPerSec := float64(tokensReceived) / generationTime.Seconds()
		fmt.Printf("Tokens received: %d\n", tokensReceived)
		fmt.Printf("Time to first token: %v\n", generationTime)
		fmt.Printf("Tokens per second: %.2f\n", tokensPerSec)
	} else {
		fmt.Println("No tokens received")
		os.Exit(1)
	}
}

