package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"time"
)

type CompletionRequest struct {
	Model    string                   `json:"model"`
	Messages []map[string]string      `json:"messages"`
	Stream   bool                     `json:"stream"`
}

type CompletionChunk struct {
	Choices []struct {
		Delta struct {
			Content string `json:"content"`
		} `json:"delta"`
	} `json:"choices"`
}

func main() {
	prompt := "Write a short story."
	if len(os.Args) > 1 {
		prompt = os.Args[1]
	}

	url := "http://localhost:8081/v1/chat/completions"

	reqBody := CompletionRequest{
		Model: "test",
		Messages: []map[string]string{
			{"role": "user", "content": prompt},
		},
		Stream: true,
	}

	jsonData, _ := json.Marshal(reqBody)

	req, _ := http.NewRequest("POST", url, bytes.NewBuffer(jsonData))
	req.Header.Set("Content-Type", "application/json")

	client := &http.Client{Timeout: 120 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(resp.Body)
		fmt.Fprintf(os.Stderr, "HTTP %d: %s\n", resp.StatusCode, string(body))
		os.Exit(1)
	}

	start := time.Now()
	firstToken := time.Time{}
	tokenCount := 0

	reader := io.Reader(resp.Body)
	buf := make([]byte, 4096)
	lineBuf := ""

	for {
		n, err := reader.Read(buf)
		if n > 0 {
			lineBuf += string(buf[:n])

			for {
			nl:
				for i := 0; i < len(lineBuf); i++ {
					if lineBuf[i] == '\n' {
						line := lineBuf[:i]
						lineBuf = lineBuf[i+1:]

						if len(line) == 0 || line[0] != '{' {
							goto nl
						}

						var chunk CompletionChunk
						if json.Unmarshal([]byte(line), &chunk) == nil {
							if len(chunk.Choices) > 0 && chunk.Choices[0].Delta.Content != "" {
								if firstToken.IsZero() {
									firstToken = time.Now()
								}
								tokenCount++
							}
						}
						goto nl
					}
				}
				if len(lineBuf) > 0 && lineBuf[len(lineBuf)-1] == '\n' {
					goto nl
				}
				break
			}
		}
		if err != nil {
			break
		}
	}

	if firstToken.IsZero() {
		fmt.Println("No tokens received")
		os.Exit(1)
	}

	elapsed := firstToken.Sub(start)
	tps := float64(tokenCount) / elapsed.Seconds()

	fmt.Printf("Tokens: %d\n", tokenCount)
	fmt.Printf("Time: %.2fs\n", elapsed.Seconds())
	fmt.Printf("Speed: %.2f tokens/sec\n", tps)
}
